1|// Kokoro client for the offline pipeline: calls the deployed
2|// lectoria-narration/narrate Modal function. The Modal SDK reads
3|// MODAL_TOKEN_ID / MODAL_TOKEN_SECRET from env itself; this module
4|// never reads, logs, or passes them. Errors are short and generic.
5|import { ModalClient } from "modal";
6|
7|export interface KokoroSynthResult {
8|  mp3: Uint8Array;
9|  durationSec: number;
10|  spans: { t0: number; t1: number }[];
11|  gpuSec: number;
12|}
13|
14|export interface KokoroClient {
15|  synthesize(req: { texts: string[]; gaps: number[]; voice: string; speed: number }): Promise<KokoroSynthResult>;
16|}
17|
18|function validShape(value: unknown, texts: number): value is KokoroSynthResult {
19|  if (typeof value !== "object" || value === null) return false;
20|  const out = value as Record<string, unknown>;
21|  const mp3 = out.mp3;
22|  if (!(mp3 instanceof Uint8Array) && !Buffer.isBuffer(mp3)) return false;
23|  if (typeof out.durationSec !== "number" || !Number.isFinite(out.durationSec)) return false;
24|  if (typeof out.gpuSec !== "number" || !Number.isFinite(out.gpuSec)) return false;
25|  if (!Array.isArray(out.spans) || out.spans.length !== texts) return false;
26|  return out.spans.every(
27|    (span) =>
28|      typeof span === "object" &&
29|      span !== null &&
30|      typeof (span as { t0: unknown }).t0 === "number" &&
31|      Number.isFinite((span as { t0: number }).t0) &&
32|      typeof (span as { t1: unknown }).t1 === "number" &&
33|      Number.isFinite((span as { t1: number }).t1),
34|  );
35|}
36|
37|export function createKokoroClient(): KokoroClient {
38|  return {
39|    synthesize: async ({ texts, gaps, voice, speed }) => {
40|      const modal = new ModalClient();
41|      const fn = await modal.functions.fromName("lectoria-narration", "narrate");
42|      let lastError: unknown = null;
43|      for (let attempt = 1; attempt <= 2; attempt++) {
44|        try {
45|          const out = await fn.remote([], { texts, gaps, voice, speed });
46|          if (!validShape(out, texts.length)) throw new Error("narration synthesize failed");
47|          return { mp3: new Uint8Array(out.mp3), durationSec: out.durationSec, spans: out.spans, gpuSec: out.gpuSec };
48|        } catch (error) {
49|          lastError = error;
50|        }
51|      }
52|      throw lastError instanceof Error ? lastError : new Error("narration synthesize failed");
53|    },
54|  };
55|}

