1|// Step 5: one Kokoro mp3 plus sentence timings per chapter, cached by
2|// content hash so a second reader of the same text gets it free. Last
3|// step: every cache key includes the frozen textVersion, so switching
4|// between the Blob and local stores later is a re-run with identical keys.
5|import { createHash } from "node:crypto";
6|import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
7|import { dirname, join } from "node:path";
8|import { ensureChapterNarration } from "../core/narration-cache";
9|import type { NarrationDeps } from "../core/narration-cache";
10|import {
11|  NARRATION_FORMAT,
12|  NARRATION_MODEL,
13|  NARRATION_SPEED,
14|  NARRATION_VOICE,
15|  actualNarrationMicro,
16|  chapterChunks,
17|  parseChapterNarration,
18|} from "../core/narration";
19|import type { ChapterNarration } from "../core/narration";
20|import type { Book } from "../core/types";
21|import { decide, narrateKeys } from "./freshness";
22|import type { StepCtx } from "./ingest";
23|
24|export const NARRATION_CONCURRENCY = 4;
25|const DEFAULT_CAP_USD = 2;
26|
27|export interface NarrateStats {
28|  generated: number;
29|  cached: number;
30|  gpuSec: number;
31|  estimatedMicro: number;
32|  actualMicro: number;
33|  stopped: boolean;
34|}
35|
36|function parseCapUsd(raw: string | undefined): number {
37|  if (raw === undefined || raw.trim() === "") return DEFAULT_CAP_USD;
38|  const value = Number(raw);
39|  return Number.isFinite(value) && value >= 0 ? value : DEFAULT_CAP_USD;
40|}
