42|// Local store for dev and for Oz before Blob is wired: audio at
43|// public/<key>.mp3 with src /<key>.mp3, manifest json next to it.
44|export function createLocalNarrationStore(publicDir: string): NarrationDeps["store"] {
45|  const pathOf = (key: string, ext: string): string => join(publicDir, `${key}${ext}`);
46|  return {
47|    getManifest: async (key: string) => {
48|      try {
49|        return parseChapterNarration(JSON.parse(readFileSync(pathOf(key, ".json"), "utf8")) as unknown);
50|      } catch {
51|        return null;
52|      }
53|    },
54|    putAudio: async (key: string, mp3: Uint8Array) => {
55|      const path = pathOf(key, ".mp3");
56|      mkdirSync(dirname(path), { recursive: true });
57|      writeFileSync(path, Buffer.from(mp3));
58|      return `/${key}.mp3`;
59|    },
60|    putManifest: async (key: string, value: ChapterNarration) => {
61|      const path = pathOf(key, ".json");
62|      mkdirSync(dirname(path), { recursive: true });
63|      writeFileSync(path, `${JSON.stringify(value)}\n`);
64|    },
65|  };
66|}
67|
68|// Blob store with the same keys, so switching stores is a re-run.
69|export function createBlobNarrationStore(): NarrationDeps["store"] {
70|  return {
71|    getManifest: async (key: string) => {
72|      const { list } = await import("@vercel/blob");
73|      const path = `${key}.json`;
74|      const page = await list({ prefix: path, limit: 10 });
75|      const url = page.blobs.find((b) => b.pathname === path)?.url ?? null;
76|      if (!url) return null;
77|      try {
78|        const response = await fetch(url);
79|        if (!response.ok) return null;
80|        return parseChapterNarration((await response.json()) as unknown);
81|      } catch {
82|        return null;
83|      }
84|    },
85|    putAudio: async (key: string, mp3: Uint8Array) => {
86|      const { put } = await import("@vercel/blob");
87|      const blob = await put(`${key}.mp3`, Buffer.from(mp3), {
88|        access: "public",
89|        addRandomSuffix: false,
90|        allowOverwrite: false,
91|        contentType: "audio/mpeg",
92|        cacheControlMaxAge: 31536000,
93|      });
94|      return blob.url;
95|    },
96|    putManifest: async (key: string, value: ChapterNarration) => {
97|      const { put } = await import("@vercel/blob");
98|      await put(`${key}.json`, JSON.stringify(value), {
99|        access: "public",
100|        addRandomSuffix: false,
101|        allowOverwrite: false,
102|        contentType: "application/json",
103|        cacheControlMaxAge: 31536000,
104|      });
105|    },
106|  };
107|}
108|
109|export async function runNarrate(
110|  ctx: StepCtx,
111|  deps: {
112|    synthesize: NarrationDeps["synthesize"];
113|    store?: NarrationDeps["store"];
114|    capUsd?: number;
115|  },
116|): Promise<NarrateStats> {
117|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
118|  const keys = narrateKeys(ctx.dir);
119|  if (decide(ctx.force, keys.recorded, keys.current).reuse) {
120|    console.log("narrate: reuse (inputs unchanged)");
121|    return { generated: 0, cached: book.chapters.length, gpuSec: 0, estimatedMicro: 0, actualMicro: 0, stopped: false };
122|  }
123|  const outPath = join(ctx.dir, "narration.json");
124|  const previous = (() => {
125|    try {
126|      return JSON.parse(readFileSync(outPath, "utf8")) as {
127|        chapters?: Record<string, ChapterNarration>;
128|      };
129|    } catch {
130|      return null;
131|    }
132|  })();
133|  const byKey = new Map<string, ChapterNarration>();
134|  for (const manifest of Object.values(previous?.chapters ?? {})) byKey.set(manifest.key, manifest);
135|  const store = deps.store ?? (process.env.BLOB_READ_WRITE_TOKEN ? createBlobNarrationStore() : createLocalNarrationStore("public"));
136|  const capMicro = Math.round((deps.capUsd ?? parseCapUsd(process.env.NARRATION_CAP_USD)) * 1_000_000);
137|  let spent = 0;
138|  const budget = {
139|    reserve: async (micro: number) => {
140|      if (spent + micro > capMicro) return false;
141|      spent += micro;
142|      return true;
143|    },
144|    refund: async (micro: number) => {
145|      spent -= micro;
146|    },
147|  };
148|  const stats: NarrateStats = { generated: 0, cached: 0, gpuSec: 0, estimatedMicro: 0, actualMicro: 0, stopped: false };
149|  const chapters: Record<string, ChapterNarration> = {};
150|  // Bounded pool that stops starting new chapters once the cap refuses,
151|  // so the run reports instead of spending more.
152|  let next = 0;
153|  const sha256Hex = async (text: string): Promise<string> => createHash("sha256").update(text).digest("hex");
154|  const one = async (ch: number): Promise<void> => {
155|    const paras = book.paragraphs
156|      .filter((p) => p.ch === ch)
157|      .sort((a, b) => a.n - b.n)
158|      .map((p) => ({ n: p.n, text: p.text }));
159|    const { chunks, gaps } = chapterChunks(paras);
160|    let gpuSec = 0;
161|    const result = await ensureChapterNarration(
162|      { chunks, gaps },
163|      {
164|        sha256Hex,
165|        index: {
166|          get: async (key: string) => byKey.get(key) ?? null,
167|          set: async (key: string, value: ChapterNarration) => {
168|            byKey.set(key, value);
169|          },
170|        },
171|        store,
172|        budget,
173|        synthesize: async (req) => {
174|          const out = await deps.synthesize(req);
175|          gpuSec = out.gpuSec;
176|          return out;
177|        },
178|      },
179|    );
180|    if (result.status === "error" && result.code === "budget") {
181|      stats.stopped = true;
182|      return;
183|    }
184|    if (result.status !== "ready") throw new Error(`narration failed for chapter ${ch}`);
185|    chapters[String(ch)] = result.narration;
186|    if (result.cached) {
187|      stats.cached += 1;
188|      console.log(`ch ${ch}: cached`);
189|    } else {
190|      stats.generated += 1;
191|      stats.gpuSec += gpuSec;
192|      stats.estimatedMicro += result.costMicro;
193|      stats.actualMicro += actualNarrationMicro(gpuSec);
194|      console.log(`ch ${ch}: generated ${result.narration.durationSec.toFixed(1)} s audio, ${gpuSec.toFixed(1)} s gpu`);
195|    }
196|  };
197|  const workers = new Array(Math.min(NARRATION_CONCURRENCY, book.chapters.length)).fill(null).map(async () => {
198|    while (next < book.chapters.length && !stats.stopped) {
199|      const chapter = book.chapters[next] as Book["chapters"][number];
200|      next += 1;
201|      await one(chapter.ch);
202|    }
203|  });
204|  await Promise.all(workers);
205|  const complete = !stats.stopped && Object.keys(chapters).length === book.chapters.length;
206|  writeFileSync(
207|    outPath,
208|    `${JSON.stringify({
209|      textVersion: book.textVersion,
210|      provenance: {
211|        input: complete ? keys.current : ((previous as { provenance?: { input?: unknown } } | null)?.provenance?.input ?? keys.current),
212|        voice: NARRATION_VOICE,
213|        model: NARRATION_MODEL,
214|        speed: NARRATION_SPEED,
215|        format: NARRATION_FORMAT,
216|        chapters_generated: stats.generated,
217|        chapters_cached: stats.cached,
218|        gpu_seconds: Math.round(stats.gpuSec * 10) / 10,
219|        cost_usd_estimated: Math.round((stats.estimatedMicro / 1_000_000) * 1e6) / 1e6,
220|        cost_usd_actual: Math.round((stats.actualMicro / 1_000_000) * 1e6) / 1e6,
221|      },
222|      chapters,
223|    })}\n`,
224|  );
225|  console.log(
226|    `narrate: ${stats.generated} generated, ${stats.cached} cached, ` +
227|      `estimated $${(stats.estimatedMicro / 1_000_000).toFixed(4)}, actual $${(stats.actualMicro / 1_000_000).toFixed(4)}` +
228|      (stats.stopped ? ` (stopped at cap $${(capMicro / 1_000_000).toFixed(2)})` : ""),
229|  );
230|  return stats;
231|}

Read text file `core/narration.ts`.
1|// Pure narration logic: sentence split, chunking, cache keys, manifest
2|// validation, playback helpers, and cost math. No env, no network,
3|// no crypto, no node: imports; callers inject hashing.
4|export const NARRATION_VOICE = "af_heart";
5|export const NARRATION_MODEL = "kokoro-82m/0.9.4";
6|export const NARRATION_SPEED = 0.95;
7|export const NARRATION_FORMAT = 1;
8|export const SENTENCE_GAP_SEC = 0.3;
9|export const PARAGRAPH_GAP_SEC = 0.7;
10|
11|export interface SentenceSpan {
12|  start: number;
13|  end: number;
14|}
15|
16|export interface NarrationChunk {
17|  n: number;
18|  start: number;
19|  end: number;
20|  text: string;
21|}
22|
23|const CLOSERS = new Set(["”", "’", '"', "'", ")", "]"]);
24|
25|// Lowercase words that end with a period without ending a sentence.
26|const ABBREVIATIONS = new Set([
27|  "mr", "mrs", "ms", "dr", "st", "mt", "prof", "sr", "jr",
28|  "rev", "lt", "col", "gen", "capt", "sgt", "ave", "blvd", "rd", "no",
29|]);
30|
31|function isTerminator(char: string): boolean {
32|  return char === "." || char === "!" || char === "?" || char === "…";
33|}
34|
35|function isSpace(char: string | undefined): boolean {
36|  return char === undefined || /\s/.test(char);
37|}
38|
39|// Word of letters directly before index (exclusive), lowercased.
40|function wordBefore(text: string, index: number): string {
41|  let i = index - 1;
42|  while (i >= 0 && /[A-Za-z]/.test(text[i] as string)) i -= 1;
43|  return text.slice(i + 1, index).toLowerCase();
44|}
45|
46|function wordCount(piece: string): number {
47|  const words = piece.split(/\s+/).filter((w) => w.length > 0);
48|  return words.length;
49|}
50|
51|// Char offsets into the paragraph text, trimmed of surrounding
52|// whitespace, covering every non-space char. A sentence ends at a
53|// terminator plus closing quotes/brackets followed by whitespace.
54|export function splitSentences(text: string): SentenceSpan[] {
55|  const raw: SentenceSpan[] = [];
56|  let pieceStart = -1;
57|  let i = 0;
58|  while (i < text.length) {
59|    const char = text[i] as string;
60|    if (/\s/.test(char)) {
61|      i += 1;
62|      continue;
63|    }
64|    if (pieceStart === -1) pieceStart = i;
65|    if (isTerminator(char)) {
66|      let end = i + 1;
67|      while (end < text.length && CLOSERS.has(text[end] as string)) end += 1;
68|      if (isSpace(text[end])) {
69|        if (char === ".") {
70|          const word = wordBefore(text, i);
71|          const singleInitial = /^[A-Z]$/.test(text.slice(i - 1, i));
72|          if (singleInitial || ABBREVIATIONS.has(word)) {
73|            i += 1;
74|            continue;
75|          }
76|        }
77|        // Trim trailing whitespace inside the piece (there is none:
78|        // the piece ends at a terminator or closer).
79|        raw.push({ start: pieceStart, end });
80|        pieceStart = -1;
81|        i = end;
82|        continue;
83|      }
84|    }
85|    i += 1;
86|  }
87|  if (pieceStart !== -1) {
88|    let end = text.length;
89|    while (end > pieceStart && /\s/.test(text[end - 1] as string)) end -= 1;
90|    raw.push({ start: pieceStart, end });
91|  }
92|  if (raw.length === 0) return [];
93|  // Merge a piece shorter than 3 words into the previous sentence
94|  // (or the next one if first), keeping offsets exact.
95|  const merged: SentenceSpan[] = [];
96|  for (const span of raw) {
97|    const piece = text.slice(span.start, span.end);
98|    if (wordCount(piece) >= 3 || merged.length === 0) {
99|      merged.push({ ...span });
100|      continue;
101|    }
102|    const prev = merged[merged.length - 1] as SentenceSpan;
103|    prev.end = span.end;
104|  }
105|  if (merged.length > 1) {
106|    const first = merged[0] as SentenceSpan;
107|    if (wordCount(text.slice(first.start, first.end)) < 3) {
108|      const next = merged[1] as SentenceSpan;
109|      next.start = first.start;
110|      merged.shift();
111|    }
112|  }
113|  return merged;
114|}
115|
116|export function chapterChunks(paragraphs: { n: number; text: string }[]): {
117|  chunks: NarrationChunk[];
118|  gaps: number[];
119|} {
120|  const chunks: NarrationChunk[] = [];
121|  const paraOf: number[] = [];
122|  paragraphs.forEach((para, paraIndex) => {
123|    for (const span of splitSentences(para.text)) {
124|      chunks.push({ n: para.n, start: span.start, end: span.end, text: para.text.slice(span.start, span.end) });
125|      paraOf.push(paraIndex);
126|    }
127|  });
128|  const gaps = chunks.map((_, i) => {
129|    if (i === chunks.length - 1) return 0;
130|    return paraOf[i] !== paraOf[i + 1] ? PARAGRAPH_GAP_SEC : SENTENCE_GAP_SEC;
131|  });
132|  return { chunks, gaps };
133|}
134|
135|export function normalizeChunkText(text: string): string {
136|  return text.normalize("NFC").replace(/\s+/g, " ").trim();
137|}
138|
139|// Canonical string the caller hashes with SHA-256. Same text + voice +
140|// model + speed => same string; any edit changes it.
141|export function narrationKeyInput(args: {
142|  chunks: { text: string }[];
143|  voice: string;
144|  model: string;
145|  speed: number;
146|  format: number;
147|}): string {
148|  const body = args.chunks.map((c) => normalizeChunkText(c.text)).join("\n");
149|  return `narration/${args.format}\nvoice:${args.voice}\nmodel:${args.model}\nspeed:${args.speed}\n${body}`;
150|}
151|
152|export function narrationKey(hashHex: string, voice: string): string {
153|  return `narration/v${NARRATION_FORMAT}/${voice}/${hashHex.slice(0, 32)}`;
154|}
155|
156|export function narrationAudioPath(key: string): string {
157|  return `${key}.mp3`;
158|}
159|
160|export function narrationManifestPath(key: string): string {
161|  return `${key}.json`;
162|}
163|
164|export interface ChapterChunkTiming {
165|  n: number;
166|  start: number;
167|  end: number;
168|  t0: number;
169|  t1: number;
170|}
171|
172|export interface ChapterNarration {
173|  format: 1;
174|  key: string;
175|  src: string;
176|  durationSec: number;
177|  voice: string;
178|  model: string;
179|  speed: number;
180|  chunks: ChapterChunkTiming[];
181|}
182|
183|function isRecord(json: unknown): json is Record<string, unknown> {
184|  return typeof json === "object" && json !== null && !Array.isArray(json);
185|}
186|
187|// Strict parse at the trust boundary: the reader fetches this JSON,
188|// so any bad field throws instead of half-playing.
189|export function parseChapterNarration(json: unknown): ChapterNarration {
190|  if (!isRecord(json)) throw new Error("invalid narration manifest");
191|  if (json.format !== NARRATION_FORMAT) throw new Error("invalid narration manifest");
192|  if (typeof json.key !== "string" || json.key.length === 0) throw new Error("invalid narration manifest");
193|  if (typeof json.src !== "string" || !isSafeSrc(json.src)) throw new Error("invalid narration manifest");
194|  if (typeof json.durationSec !== "number" || !Number.isFinite(json.durationSec) || json.durationSec <= 0) {
195|    throw new Error("invalid narration manifest");
196|  }
197|  if (typeof json.voice !== "string" || json.voice.length === 0) throw new Error("invalid narration manifest");
198|  if (typeof json.model !== "string" || json.model.length === 0) throw new Error("invalid narration manifest");
199|  if (typeof json.speed !== "number" || !Number.isFinite(json.speed)) throw new Error("invalid narration manifest");
200|  if (!Array.isArray(json.chunks) || json.chunks.length === 0) throw new Error("invalid narration manifest");
201|  const chunks: ChapterChunkTiming[] = json.chunks.map((entry) => {
202|    if (!isRecord(entry)) throw new Error("invalid narration manifest");
203|    const { n, start, end, t0, t1 } = entry;
204|    if (typeof n !== "number" || !Number.isInteger(n)) throw new Error("invalid narration manifest");
205|    if (typeof start !== "number" || !Number.isInteger(start) || start < 0) throw new Error("invalid narration manifest");
206|    if (typeof end !== "number" || !Number.isInteger(end) || end <= start) throw new Error("invalid narration manifest");
207|    for (const t of [t0, t1]) {
208|      if (typeof t !== "number" || !Number.isFinite(t)) throw new Error("invalid narration manifest");
209|    }
210|    const from = t0 as number;
211|    const to = t1 as number;
212|    if (!(0 <= from && from < to && to <= (json.durationSec as number) + 0.05)) {
213|      throw new Error("invalid narration manifest");
214|    }
215|    return { n: n as number, start: start as number, end: end as number, t0: from, t1: to };
216|  });
217|  for (let i = 1; i < chunks.length; i++) {
218|    if ((chunks[i] as ChapterChunkTiming).t0 < (chunks[i - 1] as ChapterChunkTiming).t0) {
219|      throw new Error("invalid narration manifest");
220|    }
221|  }
222|  return {
223|    format: 1,
224|    key: json.key as string,
225|    src: json.src as string,
226|    durationSec: json.durationSec as number,
227|    voice: json.voice as string,
228|    model: json.model as string,
229|    speed: json.speed as number,
230|    chunks,
231|  };
232|}
233|
234|function isSafeSrc(src: string): boolean {
235|  if (src.startsWith("/narration/")) return true;
236|  if (src.startsWith("https://")) {
237|    try {
238|      new URL(src);
239|      return true;
240|    } catch {
241|      return false;
242|    }
243|  }
244|  return false;
245|}
246|
247|// Binary search: index of the last chunk with t0 <= t, so the highlight
248|// stays on a sentence through the gap after it. -1 before the first.
249|export function activeChunkAt(chunks: { t0: number }[], tSec: number): number {
250|  let lo = 0;
251|  let hi = chunks.length - 1;
252|  let found = -1;
253|  while (lo <= hi) {
254|    const mid = (lo + hi) >> 1;
255|    if ((chunks[mid] as { t0: number }).t0 <= tSec) {
256|      found = mid;
257|      lo = mid + 1;
258|    } else {
259|      hi = mid - 1;
260|    }
261|  }
262|  return found;
263|}
264|
265|// Playback range for a scene: t0 of the first chunk with n >= startN
266|// through t1 of the last chunk with n <= endN. Null when empty.
267|export function sceneSpan(
268|  narration: { chunks: { n: number; t0: number; t1: number }[] },
269|  startN: number,
270|  endN: number,
271|): { startSec: number; endSec: number } | null {
272|  let startSec: number | null = null;
273|  let endSec: number | null = null;
274|  for (const chunk of narration.chunks) {
275|    if (chunk.n < startN || chunk.n > endN) continue;
276|    if (startSec === null) startSec = chunk.t0;
277|    endSec = chunk.t1;
278|  }
279|  if (startSec === null || endSec === null) return null;
280|  return { startSec, endSec };
