1|// Shared narration cache flow: key -> index -> store -> lock -> budget
2|// -> synthesize -> put -> index. Used offline for Oz now and on demand
3|// for uploaded books later. Pure: every side effect arrives via deps.
4|import {
5|  NARRATION_FORMAT,
6|  NARRATION_MODEL,
7|  NARRATION_SPEED,
8|  NARRATION_VOICE,
9|  estimateNarrationMicro,
10|  narrationKey,
11|  narrationKeyInput,
12|  parseChapterNarration,
13|} from "./narration";
14|import type { ChapterNarration, NarrationChunk } from "./narration";
15|
16|export interface NarrationDeps {
17|  sha256Hex(text: string): Promise<string>;
18|  index: {
19|    get(key: string): Promise<ChapterNarration | null>;
20|    set(key: string, value: ChapterNarration): Promise<void>;
21|  };
22|  store: {
23|    getManifest(key: string): Promise<ChapterNarration | null>;
24|    putAudio(key: string, mp3: Uint8Array): Promise<string>;
25|    putManifest(key: string, value: ChapterNarration): Promise<void>;
26|  };
27|  lock?: {
28|    acquire(key: string): Promise<string | null>;
29|    release(key: string, token: string): Promise<void>;
30|  };
31|  budget?: {
32|    reserve(micro: number): Promise<boolean>;
33|    refund(micro: number): Promise<void>;
34|  };
35|  synthesize(req: {
36|    texts: string[];
37|    gaps: number[];
38|    voice: string;
39|    speed: number;
40|  }): Promise<{
41|    mp3: Uint8Array;
42|    durationSec: number;
43|    spans: { t0: number; t1: number }[];
44|    gpuSec: number;
45|  }>;
46|}
47|
48|export type EnsureResult =
49|  | { status: "ready"; narration: ChapterNarration; cached: boolean; costMicro: number }
50|  | { status: "pending" }
51|  | { status: "error"; code: "budget" | "failed" };
52|
53|export async function ensureChapterNarration(
54|  input: { chunks: NarrationChunk[]; gaps: number[]; voice?: string; speed?: number },
55|  deps: NarrationDeps,
56|): Promise<EnsureResult> {
57|  const voice = input.voice ?? NARRATION_VOICE;
58|  const speed = input.speed ?? NARRATION_SPEED;
59|  const hash = await deps.sha256Hex(
60|    narrationKeyInput({ chunks: input.chunks, voice, model: NARRATION_MODEL, speed, format: NARRATION_FORMAT }),
61|  );
62|  const key = narrationKey(hash, voice);
63|
64|  const indexed = await deps.index.get(key);
65|  if (indexed) return { status: "ready", narration: indexed, cached: true, costMicro: 0 };
66|
67|  const stored = await deps.store.getManifest(key);
68|  if (stored) {
69|    await deps.index.set(key, stored);
70|    return { status: "ready", narration: stored, cached: true, costMicro: 0 };
71|  }
72|
73|  let lease: string | null = null;
74|  if (deps.lock) {
75|    lease = await deps.lock.acquire(key);
76|    if (lease === null) return { status: "pending" };
77|    // Another holder may have just finished while we waited.
78|    const raced = await deps.index.get(key);
79|    if (raced) {
80|      await releaseQuietly(deps, key, lease);
81|      return { status: "ready", narration: raced, cached: true, costMicro: 0 };
82|    }
83|  }
84|
85|  const release = async (): Promise<void> => {
86|    if (deps.lock && lease !== null) await releaseQuietly(deps, key, lease);
87|  };
88|
89|  const totalChars = input.chunks.reduce((sum, c) => sum + c.text.length, 0);
90|  const estimate = estimateNarrationMicro(totalChars);
91|  if (deps.budget) {
92|    const ok = await deps.budget.reserve(estimate);
93|    if (!ok) {
94|      await release();
95|      return { status: "error", code: "budget" };
96|    }
97|  }
98|
99|  let refunded = false;
100|  const refundOnce = async (): Promise<void> => {
101|    if (deps.budget && !refunded) {
102|      refunded = true;
103|      try {
104|        await deps.budget.refund(estimate);
105|      } catch {
106|        // The cap is advisory; a lost refund only skews accounting.
107|      }
108|    }
109|  };
110|
111|  try {
112|    const out = await deps.synthesize({ texts: input.chunks.map((c) => c.text), gaps: input.gaps, voice, speed });
113|    if (out.spans.length !== input.chunks.length) throw new Error("span count mismatch");
114|    const src = await deps.store.putAudio(key, out.mp3);
115|    const manifest = parseChapterNarration({
116|      format: NARRATION_FORMAT,
117|      key,
118|      src,
119|      durationSec: out.durationSec,
120|      voice,
121|      model: NARRATION_MODEL,
122|      speed,
123|      chunks: input.chunks.map((chunk, i) => ({
124|        n: chunk.n,
125|        start: chunk.start,
126|        end: chunk.end,
127|        t0: (out.spans[i] as { t0: number; t1: number }).t0,
128|        t1: (out.spans[i] as { t0: number; t1: number }).t1,
129|      })),
130|    });
131|    await deps.store.putManifest(key, manifest);
132|    await deps.index.set(key, manifest);
133|    await release();
134|    // The cap counts what was reserved; never refund on success.
135|    return { status: "ready", narration: manifest, cached: false, costMicro: estimate };
136|  } catch {
137|    await refundOnce();
138|    await release();
139|    return { status: "error", code: "failed" };
140|  }
141|}
142|
143|async function releaseQuietly(deps: NarrationDeps, key: string, token: string): Promise<void> {
144|  try {
145|    await deps.lock?.release(key, token);
146|  } catch {
147|    // The lock has a TTL; a lost release expires on its own.
148|  }
149|}

