12|function setupBook(dir: string): void {
13|  writeFileSync(
14|    join(dir, "book.json"),
15|    JSON.stringify({
16|      id: "oz",
17|      title: "Oz",
18|      author: "A",
19|      source: { gutenberg: 55, url: "u" },
20|      textVersion: "sha256:x",
21|      chapters: [
22|        { ch: 1, title: "One", start_n: 1, end_n: 2 },
23|        { ch: 2, title: "Two", start_n: 3, end_n: 4 },
24|      ],
25|      paragraphs: [1, 2, 3, 4].map((n) => ({
26|        id: `c${n <= 2 ? 1 : 2}p${n}`,
27|        ch: n <= 2 ? 1 : 2,
28|        n,
29|        text: `Dorothy walked the long dusty road with Toto beside her.`,
30|      })),
31|    }),
32|  );
33|}
34|
35|function fakeSynthesize() {
36|  let calls = 0;
37|  const synthesize: NarrationDeps["synthesize"] = async ({ texts, gaps }) => {
38|    calls += 1;
39|    return {
40|      mp3: new Uint8Array([calls]),
41|      durationSec: texts.length * 2 + gaps.reduce((a, b) => a + b, 0),
42|      spans: texts.map((_, i) => ({ t0: i * 2, t1: i * 2 + 1.5 })),
43|      gpuSec: 7.1,
44|    };
45|  };
46|  return { synthesize, calls: () => calls };
47|}
48|
49|function memoryStore() {
50|  const audio = new Map<string, Uint8Array>();
51|  const manifests = new Map<string, ChapterNarration>();
52|  const store: NarrationDeps["store"] = {
53|    getManifest: async (key: string) => manifests.get(key) ?? null,
54|    putAudio: async (key: string, mp3: Uint8Array) => {
55|      audio.set(key, mp3);
56|      return `https://blob.example.com/${key}.mp3`;
57|    },
58|    putManifest: async (key: string, value: ChapterNarration) => {
59|      manifests.set(key, value);
60|    },
61|  };
62|  return { store, audio, manifests };
63|}
64|
65|function readNarration(dir: string): { provenance: Record<string, unknown>; chapters: Record<string, ChapterNarration> } {
66|  return JSON.parse(readFileSync(join(dir, "narration.json"), "utf8")) as {
67|    provenance: Record<string, unknown>;
68|    chapters: Record<string, ChapterNarration>;
69|  };
70|}
71|
72|describe("runNarrate", () => {
73|  it("writes manifests for every chapter, then reuses them at zero cost", async () => {
74|    const dir = mkdtempSync(join(tmpdir(), "narrate-"));
75|    setupBook(dir);
76|    const { synthesize, calls } = fakeSynthesize();
77|    const { store } = memoryStore();
78|    const ctx = { bookKey: "oz", force: false, dir };
79|
80|    const first = await runNarrate(ctx, { synthesize, store, capUsd: 2 });
