1|// CLI: npm run build:book -- oz [--step ingest|segment|classify|resplit|cluster|narrate] [--force] [--dry-run]
2|// --dry-run prints one freshness line per selected step and stops before
3|// any client, write, or network call.
4|import { readFileSync } from "node:fs";
5|import { join } from "node:path";
6|import { runClassify } from "./classify";
7|import { runCluster } from "./cluster-tracks";
8|import { bookConfig, runIngest } from "./ingest";
9|import type { StepCtx } from "./ingest";
10|import { planSteps } from "./freshness";
11|import type { FreshStep } from "./freshness";
12|import { createJevClient } from "./jev";
13|import { createMetaClient } from "./meta";
14|import { runNarrate } from "./narrate";
15|import { runResplit } from "./resplit";
16|import { runSegment } from "./segment";
17|
18|const STEPS = ["ingest", "segment", "classify", "resplit", "cluster", "narrate"] as const;
19|
20|function loadEnv(): void {
21|  try {
22|    if (typeof process.loadEnvFile === "function") process.loadEnvFile(".env.local");
23|  } catch {
24|    // No .env.local is fine; env may come from elsewhere.
25|  }
26|}
27|
28|function env(name: string, fallback?: string): string {
29|  const value = process.env[name] ?? fallback;
30|  if (value === undefined || value === "") throw new Error(`${name} is not set`);
31|  return value;
32|}
33|
34|async function main(): Promise<void> {
35|  loadEnv();
36|  const args = process.argv.slice(2);
37|  const bookKey = args.find((a) => !a.startsWith("--")) ?? "";
38|  const stepFlag = args.indexOf("--step");
39|  const stepArg = stepFlag === -1 ? undefined : args[stepFlag + 1];
40|  const force = args.includes("--force");
41|  const dryRun = args.includes("--dry-run");
42|  if (!bookKey) throw new Error("usage: build:book <book> [--step ingest|segment|classify|resplit|cluster|narrate] [--force] [--dry-run]");
43|  bookConfig(bookKey); // fails fast on unknown keys with the valid list
44|  const only = stepArg ?? "";
45|  if (only !== "" && !(STEPS as readonly string[]).includes(only)) {
46|    throw new Error(`unknown step "${only}", valid steps: ${STEPS.join(", ")}`);
47|  }
48|  const ctx: StepCtx = { bookKey, force, dir: join("data", "books", bookKey) };
49|  if (dryRun) {
50|    const selected = (only === "" ? [...STEPS] : [only]) as (typeof STEPS)[number][];
51|    if (selected.includes("ingest")) console.log("ingest: not checked in dry run (frozen textVersion rule)");
52|    for (const plan of planSteps(ctx.dir, selected.filter((s): s is FreshStep => s !== "ingest"), force)) {
53|      console.log(`${plan.step}: ${plan.reuse ? "reuse" : "redo"} (${plan.reason})`);
54|    }
55|    return;
56|  }
57|  const run: Record<(typeof STEPS)[number], boolean> = {
58|    ingest: only === "" || only === "ingest",
59|    segment: only === "" || only === "segment",
60|    classify: only === "" || only === "classify",
61|    resplit: only === "" || only === "resplit",
62|    cluster: only === "" || only === "cluster",
63|    narrate: only === "" || only === "narrate",
64|  };
65|  if (run.ingest) {
66|    const book = await runIngest(ctx);
67|    console.log(`ingest: ${book.chapters.length} chapters, ${book.paragraphs.length} paragraphs, ${book.textVersion}`);
68|  }
69|  if (run.segment) {
70|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
71|    console.log(`segment: ${meta.model}`);
72|    const scenes = await runSegment(ctx, { meta });
73|    console.log(`segment: ${scenes.length} scenes`);
74|  }
75|  if (run.classify) {
76|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
77|    const jev = createJevClient({ apiKey: env("JEV_API_KEY"), model: process.env.JEV_MODEL ?? "jev-1.14.0" });
78|    const scenes = await runClassify(ctx, { jev, meta });
79|    const overrides = scenes.filter((s) => s.muse_override !== null).length;
80|    const failures = scenes.filter((s) => s.final === null).length;
81|    console.log(`classify: ${scenes.length} scenes, ${overrides} overrides, ${failures} failures`);
82|  }
83|  if (run.resplit) {
84|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
85|    const jev = createJevClient({ apiKey: env("JEV_API_KEY"), model: process.env.JEV_MODEL ?? "jev-1.14.0" });
86|    const scenes = await runResplit(ctx, { jev, meta });
87|    console.log(`resplit: ${scenes.length} scenes`);
88|  }
89|  if (run.cluster) {
90|    await runCluster(ctx);
91|    console.log("cluster: wrote music-clusters.json");
92|  }
93|  if (run.narrate) {
94|    // The Kokoro client loads lazily only when this step runs, so the
95|    // other steps never touch Modal. Narration needs neither
96|    // META_API_KEY nor JEV_API_KEY.
97|    const { createKokoroClient } = await import("./kokoro");
98|    const client = createKokoroClient();
99|    await runNarrate(ctx, { synthesize: (req) => client.synthesize(req) });
100|  }
101|  printSummary(ctx.dir);
102|}
103|
104|function printSummary(dir: string): void {
105|  const book = JSON.parse(readFileSync(join(dir, "book.json"), "utf8")) as {
106|    chapters: unknown[];
107|    paragraphs: unknown[];
108|  };
109|  let scenes: { final: { vector: Record<string, number> } | null }[] = [];
110|  let overrideRate = 0;
111|  let jev = { cost_usd: 0 };
112|  let meta = { cost_usd: 0 };
113|  let total = 0;
114|  try {
115|    const analysis = JSON.parse(readFileSync(join(dir, "analysis.json"), "utf8")) as {
116|      scenes: (typeof scenes)[number][];
117|      override_rate: number;
118|      provenance: { jev: typeof jev; meta: typeof meta; total_cost_usd: number };
119|    };
120|    scenes = analysis.scenes;
121|    overrideRate = analysis.override_rate;
122|    jev = analysis.provenance.jev;
123|    meta = analysis.provenance.meta;
124|    total = analysis.provenance.total_cost_usd;
125|  } catch {
126|    // Steps after ingest may not have run yet.
127|  }
128|  const dist = new Map<string, number>();
129|  let failures = 0;
130|  for (const scene of scenes) {
131|    if (!scene.final) {
132|      failures += 1;
133|      continue;
134|    }
135|    const top = Object.entries(scene.final.vector).sort((a, b) => b[1] - a[1])[0]?.[0] ?? "?";
136|    dist.set(top, (dist.get(top) ?? 0) + 1);
137|  }
138|  console.log(`summary: ${book.chapters.length} chapters, ${book.paragraphs.length} paragraphs, ${scenes.length} scenes`);
139|  console.log(`emotions: ${[...dist.entries()].map(([id, count]) => `${id} ${count}`).join(", ") || "none yet"}`);
140|  console.log(`override rate ${((overrideRate ?? 0) * 100).toFixed(1)}%, failures ${failures}`);
141|  console.log(`cost: jev $${(jev.cost_usd ?? 0).toFixed(4)}, meta $${(meta.cost_usd ?? 0).toFixed(4)}, total $${(total ?? 0).toFixed(4)}`);
142|}
143|
144|main().catch((error: unknown) => {
145|  console.error(`error: ${(error as Error).message}`);
146|  process.exit(1);
147|});

